xml.Script:
        Colors[0] := 'AA00CC'; // Violett
        Colors[1] := 'EE0000'; // Red
        Colors[2] := 'FF800A'; // Orange
        Colors[3] := 'FFBB00'; //
        Colors[4] := 'FFFF00'; // Yellow
        Colors[5] := 'AAFF00'; //
        Colors[6] := '00DD00'; // LightGreen
        Colors[7] := '0055EE'; // Blue
        clWhite   := 'FFFFFF';
        clCream   := 'FFFFAA';

        R := 0.5;
        H := R;
        D := R / sqrt(6);

        for i := 0 to 39 do begin
            x[i] := R * cos(2 * Pi / 40 * (i+5));
            y[i] := R * sin(2 * Pi / 40 * (i+5));
        end;

        function FromTo(iFrom, iTo);
        begin
          Result := IntToStr(iFrom);
          for i := iFrom + 1 to iTo do
              Result := Result + ';' + IntToStr(i);
          for i := iFrom - 1 downto iTo do
              Result := Result + ';' + IntToStr(i);
        end;
